import {competitionFilter,competitionSummary,participationLabel} from './competition-ui.js';
import {tr,html as l10n} from './i18n.js';
import {esc,icon,button,link,head,empty,badge,date,short,metric,select,panel,note,table,statusLabel,runtimeLabel} from './view.js';
const kpis=items=>`<div class="admin-kpis">${items.map(([label,value,ico,foot=''])=>`<article class="stat"><p class="stat-label">${esc(label)}</p><div class="stat-value">${esc(value??'—')}</div><p class="stat-foot">${esc(foot)}</p></article>`).join('')}</div>`;
const tabs=(items,active,action)=>`<div class="tabs">${items.map(([value,label])=>button(label,action,`data-tab="${value}"`,active===value?'primary':'secondary')).join('')}</div>`;
const filtered=(items,query,values)=>items.filter(x=>values(x).toLocaleLowerCase('vi').includes((query||'').toLocaleLowerCase('vi')));
const paged=(items,n=1)=>{const pages=Math.max(1,Math.ceil(items.length/20)),page=Math.min(Math.max(n,1),pages);return{items:items.slice((page-1)*20,page*20),page,pages,total:items.length};};
const pagination=(p,scope)=>l10n`<div class="admin-pagination"><span>${p.total} mục · Trang ${p.page}/${p.pages}</span><div>${button(tr('Trước'),'admin-page',`data-scope="${scope}" data-page="${p.page-1}" ${p.page===1?'disabled':''}`,'small')}${button(tr('Tiếp'),'admin-page',`data-scope="${scope}" data-page="${p.page+1}" ${p.page===p.pages?'disabled':''}`,'small')}</div></div>`;
export const teamLabel=(s,id)=>s.accounts?.find(a=>a.team_id===id)?.team.name||(id?.startsWith('competition:')?tr('Giải · ')+short(id.slice(12)):short(id));
export function competitionTools(c){
  const attrs=`data-id="${c.id}" data-revision="${c.revision||1}"`;
  if(c.archived_ms)return button(tr('Khôi phục'),'competition-restore',attrs,'small');
  return (['draft','open'].includes(c.status)?button(tr('Sửa'),'competition-edit',attrs,'small'):'')+(['draft','open','completed'].includes(c.status)?button(tr('Xóa'),'competition-archive',attrs,'small danger-button'):'');
}

// One column per day; failed jobs are the red foot of the same column, so the count and the date
// stay centred on it whether or not the day had failures.
export function trend(days){
  const max=Math.max(1,...days.map(d=>d.jobs));
  return l10n`<svg class="admin-trend" viewBox="0 0 700 210" role="img" aria-label="Số tác vụ tạo mỗi ngày trong 7 ngày gần nhất; cột xanh là tổng tác vụ, phần đỏ ở chân cột là tác vụ lỗi"><path class="trend-axis" d="M20 170H680"/>${days.map((d,i)=>{const center=70+i*93,h=130*d.jobs/max,bad=130*Math.min(d.failed,d.jobs)/max;return l10n`<g><title>${esc(d.day)}: ${d.jobs} tác vụ, ${d.failed} lỗi</title><rect class="trend-total" x="${center-20}" y="${170-h}" width="40" height="${h}" rx="3"/><rect class="trend-failed" x="${center-20}" y="${170-bad}" width="40" height="${bad}" rx="3"/><text x="${center}" y="${Math.max(22,160-h)}" text-anchor="middle">${d.jobs}</text><text x="${center}" y="195" text-anchor="middle">${esc(d.day.slice(5))}</text></g>`;}).join('')}</svg><div class="trend-legend"><span>Tổng tác vụ</span><span>Tác vụ lỗi</span><small>Ngày theo giờ Việt Nam · Không phải số lượt bot</small></div>`;
}
export function adminDashboard(s){
  if(s.selectedCompetition&&s.competitionSummary)return head(tr('Tổng quan ban tổ chức'),tr('Đội thi, giải đấu và tình trạng vận hành.'),link('admin?competition='+encodeURIComponent(s.selectedCompetition),tr('Quản lý đội'),'primary'))+`<div class="admin-filters scope-filter">${competitionFilter(s)}</div>`+competitionSummary(s);
  const m=s.metrics;if(!m)return head(tr('Tổng quan ban tổ chức'),tr('Theo dõi đội thi, giải đấu và worker.'))+empty(tr('Đang tải số liệu…'));
  const c=m.counts,j=m.jobs.by_status,w=m.worker,ready=w.ready&&!w.scheduler_error;
  const active=Object.entries(j).filter(([k])=>!['completed','failed','aborted'].includes(k)).reduce((n,[,v])=>n+v,0);
  return head(tr('Tổng quan ban tổ chức'),tr('Đội thi, giải đấu và tình trạng vận hành.'),link('admin',tr('Quản lý đội'),'primary'))+`<div class="admin-filters scope-filter">${competitionFilter(s)}</div>`+(s.selectedCompetition?competitionSummary(s):'')+
    (m.retention?panel(tr('Lưu trữ dữ liệu'),l10n`${m.retention.disk.warning?note(tr('Dung lượng dữ liệu đã vượt ngưỡng cảnh báo. Kiểm tra ổ đĩa và chạy dọn dữ liệu.')) : ''}<p>Dữ liệu: ${esc((m.retention.disk.data_bytes/1024**3).toFixed(2))} GiB · ${esc(m.retention.disk.percent)}% dung lượng đĩa.</p><p>Tự dọn mỗi giờ; giữ toàn bộ kết quả và replay chính thức. Lần dọn gần nhất: ${m.retention.last_cleanup?date(m.retention.last_cleanup.completed_ms):tr('Chưa chạy')}.</p>${m.retention.last_cleanup?.blocked_teams?.length?note(tr('Có đội đang ghim nhiều bản bot trong các giải cùng chạy. Cache của các bản này được giữ; BTC cần hoàn tất giải cũ trước.')):''}`,button(tr('Dọn theo chính sách'),'retention-run','','small')):'')+
    l10n`<div class="admin-status-strip">${badge(ready?'completed':'attention',ready?tr('Hub sẵn sàng'):tr('Hub cần kiểm tra'))}<span>Hàng đợi ${w.queue_depth}${w.queue_capacity?'/'+w.queue_capacity:tr(' đang chờ')}</span><span>Ưu tiên giải · ${w.queue_by_scope?.official||0} chính thức / ${w.queue_by_scope?.practice||0} luyện tập chờ</span><span>Đã chạy ${Math.floor(w.uptime_seconds/60)} phút</span><span>Cập nhật ${date(m.generated_ms)}</span></div>`+
    kpis([[tr('Đội đang quản lý'),c.teams,'users',c.archived_teams+tr(' đội đã lưu trữ')],[tr('Hồ sơ chờ duyệt'),c.pending_registrations,'file',c.pending_recoveries+tr(' yêu cầu cấp lại mật khẩu')],[tr('Giải đấu'),c.competitions,'trophy',c.attention_fixtures+tr(' trận cần xử lý')],[tr('Tác vụ đang chạy'),active,'clock',j.queued+tr(' tác vụ đang chờ')],[tr('Kiểm tra đạt · 24h'),m.last_24h.benchmark_pass_rate===null?'—':m.last_24h.benchmark_pass_rate+'%','check',tr('Tính cả benchmark lỗi / đã dừng')],[tr('P95 cao nhất · 24h'),metric(m.last_24h.benchmark_p95_max_ms),'code',tr('Trong các benchmark hoàn tất')]])+
    `<div class="admin-alerts">${c.pending_registrations?link('admin?tab=registrations',c.pending_registrations+tr(' hồ sơ chờ duyệt'),'small'):''}${c.pending_recoveries?link('admin?tab=recoveries',c.pending_recoveries+tr(' yêu cầu cấp lại'),'small'):''}${c.attention_fixtures?link('schedule',c.attention_fixtures+tr(' trận cần kiểm tra'),'small'):''}${!ready?note(w.scheduler_error||w.detail||tr('Đang chờ xử lý trong hàng đợi.')) :''}</div>`+
    `<div class="real-two-col">${panel(tr('Hoạt động 7 ngày'),trend(m.daily))}${panel(tr('Hàng đợi & worker'),l10n`<dl class="detail-list"><div><dt>Runtime</dt><dd>C++17 / C11 / Python 3.11 · ${w.graders_online||0} máy chấm · ${w.grader_slots||0} chỗ · 1 CPU ghim / trận</dd></div><div><dt>Scheduler</dt><dd>${esc(w.scheduler_error||tr('Hoạt động'))}</dd></div><div><dt>Tác vụ hiện tại</dt><dd class="mono">${esc(short(w.active_job_id)||tr('Đang rảnh'))}</dd></div><div><dt>Nền tảng</dt><dd>${esc(Object.keys(w.platforms||{}).join(', ')||tr('Đang chờ máy chấm kết nối'))}</dd></div></dl>${Object.entries(j).map(([status,count])=>`<div class="admin-job-count"><span>${badge(status)}</span><meter min="0" max="${Math.max(1,m.jobs.total)}" value="${count}" aria-label="${esc(status)}: ${count}"></meter><strong>${count}</strong></div>`).join('')}`,link('operations',tr('Mở vận hành bot'),'small'))}</div>`+
    panel(tr('Lỗi gần đây'),m.errors.length?table([tr('Mã lỗi'),tr('Số tác vụ')],m.errors.map(e=>`<tr data-key="error-${esc(e.code)}"><td class="mono">${esc(e.code)}</td><td>${e.count}</td></tr>`)):empty(tr('Chưa có tác vụ lỗi')),link('operations?status=failed',tr('Xem tác vụ lỗi'),'small'));
}

export function adminTeamsBody(s){
  let items=s.adminTab==='accounts'?s.accounts:s.adminTab==='recoveries'?s.recoveries:s.registrations;
  if(s.adminTab==='accounts')items=items.filter(a=>s.adminVisibility==='all'||(s.adminVisibility==='deleted'?!!a.team.archived_ms:!a.team.archived_ms));
  items=filtered(items,s.adminSearch,x=>s.adminTab==='accounts'?[x.username,x.team.name,x.team.email,...x.team.members.flatMap(m=>[m.student_id,m.name]),...(s.people||[]).filter(p=>p.team_id===x.team_id).flatMap(p=>[p.display_name,p.email,p.username])].join(' '):[x.team,x.username,x.email].join(' '));
  const p=paged(items,s.adminPage);let body;
  if(s.adminTab==='accounts')body=table([tr('Đội / tài khoản'),tr('Liên hệ'),tr('Trạng thái'),...(s.selectedCompetition?[tr('Trong giải')]:[]),tr('Thao tác')],p.items.map(a=>l10n`<tr data-key="account-${a.id}"><td><strong>${esc(a.team.name)}</strong><div class="mono muted">${esc(a.username)}</div><small>${a.team.members.length} thành viên</small></td><td>${esc(a.team.email)}<div class="muted">${esc(a.team.phone||'—')}</div></td><td>${badge(a.team.archived_ms?'aborted':a.locked?'paused':a.must_change_password?'pending':'completed',a.team.archived_ms?tr('Đã lưu trữ'):a.locked?tr('Tạm khóa'):a.must_change_password?tr('Chờ đổi mật khẩu'):tr('Hoạt động'))}<div class="muted">${a.delivered?tr('Đã phát tài khoản'):tr('Chưa phát tài khoản')}</div></td>${s.selectedCompetition?`<td>${esc(participationLabel(a.participation))}</td>`:''}<td><div class="table-actions">${button(tr('Xem'),'team-detail',`data-id="${a.id}"`,'small')}${a.team.archived_ms?button(tr('Khôi phục'),'team-restore',`data-id="${a.id}"`,'small'):button(tr('Sửa'),'team-edit',`data-id="${a.id}"`,'small')+button(a.locked?tr('Mở khóa'):tr('Khóa'),'account-lock',`data-id="${a.id}" data-locked="${a.locked}"`,'small')+button(tr('Cấp lại mật khẩu'),'reset-password',`data-id="${a.id}"`,'small')+(!a.delivered?button(tr('Đã phát'),'delivered',`data-id="${a.id}"`,'small'):'')+button(tr('Xóa'),'team-archive',`data-id="${a.id}"`,'small danger-button')}</div></td></tr>`));
  else if(s.adminTab==='recoveries')body=table([tr('Tài khoản'),tr('Đội / email'),tr('Gửi lúc'),tr('Thao tác')],p.items.map(r=>`<tr data-key="recovery-${r.id}"><td>${esc(r.username)}</td><td>${esc(r.team)}<div class="muted">${esc(r.email)}</div></td><td>${date(r.created_ms)}</td><td>${button(tr('Cấp lại mật khẩu'),'reset-password',`data-id="${r.account_id}"`,'small')}${button(tr('Đã xử lý'),'resolve-recovery',`data-id="${r.id}"`,'small')}</td></tr>`));
  else body=table([tr('Đội'),'Email',tr('Thành viên'),tr('Gửi lúc'),tr('Thao tác')],p.items.map(r=>`<tr data-key="registration-${r.id}"><td><strong>${esc(r.team)}</strong>${badge(r.status)}</td><td>${esc(r.email)}</td><td>${r.members.length}</td><td>${date(r.created_ms)}</td><td>${button(r.status==='pending'?tr('Xem & duyệt'):tr('Xem hồ sơ'),'review-registration',`data-id="${r.id}"`,'small primary')}</td></tr>`));
  return (items.length?body:empty(tr('Không có kết quả'),tr('Thử đổi bộ lọc hoặc từ khóa.')))+pagination(p,'teams');
}
export function adminTeams(s){
  const active=s.adminTab||'accounts';
  return head(tr('Đội & tài khoản.'),tr('Tạo đội, duyệt hồ sơ, sửa thông tin và quản lý truy cập.'),button(tr('Thêm đội'),'team-create','','primary')+button(tr('Xuất CSV'),'export-teams')+button(tr('Làm mới'),'refresh'))+
    tabs([['accounts',tr('Đội & tài khoản')],['registrations',tr('Hồ sơ đăng ký')],['recoveries',tr('Cấp lại mật khẩu')]],active,'admin-tab')+
    l10n`<div class="admin-filters team-filters">${competitionFilter(s)}<label class="field admin-search-filter"><span>Tìm kiếm</span><input class="input" name="admin-search" value="${esc(s.adminSearch||'')}" placeholder="Tên đội, tài khoản, email…" type="search"></label>${active==='accounts'?l10n`<label class="field"><span>Hiển thị</span>${select('admin-visibility',[['active',tr('Đang quản lý')],['deleted',tr('Đã lưu trữ')],['all',tr('Tất cả')]],s.adminVisibility||'active',false)}</label>`:''}</div>`+
    panel(tr('Danh sách'),`<div id="admin-table">${adminTeamsBody(s)}</div>`,active==='registrations'?l10n`<label class="field"><span>Hồ sơ</span>${select('registration-status',[['pending',tr('Chờ duyệt')],['approved',tr('Đã duyệt')],['rejected',tr('Đã từ chối')]],s.registrationStatus||'pending',false)}</label>`:'')+note(tr('Xóa đội có thể khôi phục. Lịch sử bot, tác vụ và kết quả vẫn được giữ. Cần xử lý bot dự giải của đội trước khi xóa nếu giải chưa hoàn tất.'));
}

export function operationsBody(s){
  const submissions=s.opsTab==='submissions';
  let items=submissions?s.adminSubmissions:s.adminJobs;
  if(!submissions)items=items.filter(j=>(!s.opsStatus||j.status===s.opsStatus)&&(!s.opsKind||j.kind===s.opsKind));
  items=items.filter(j=>!s.opsTeam||j.team_id===s.opsTeam);
  items=filtered(items,s.opsSearch,j=>[j.id,j.version,teamLabel(s,j.team_id)].join(' '));
  const p=paged(items,s.opsPage);
  const body=submissions?table([tr('Phiên bản'),tr('Đội'),tr('Ngôn ngữ'),tr('Biên dịch'),tr('Nộp lúc'),''],p.items.map(j=>`<tr data-key="submission-${j.id}"><td><strong>${esc(j.version)}</strong><div class="mono muted">${short(j.id)}</div></td><td>${esc(teamLabel(s,j.team_id))}</td><td>${esc(runtimeLabel(j.runtime))}</td><td>${badge(j.artifact?'completed':'pending',j.artifact?tr('Đã build'):tr('Chưa build'))}</td><td>${date(j.created_unix_ms)}</td><td>${button('Manifest','submission-manifest',`data-id="${j.id}"`,'small')}</td></tr>`)):
    table([tr('Tác vụ'),tr('Đội / giải'),tr('Loại'),tr('Trạng thái'),tr('Tạo lúc'),''],p.items.map(j=>`<tr data-key="job-${j.id}"><td class="mono">${short(j.id)}</td><td>${esc(teamLabel(s,j.team_id))}</td><td>${j.kind==='benchmark'?tr('Kiểm tra'):tr('Trận đấu')}${j.official?tr('<div class="muted">Chính thức</div>'):''}</td><td>${badge(j.status)}${j.error?`<div class="muted mono">${esc(j.error.code)}</div>`:''}</td><td>${date(j.created_unix_ms)}</td><td>${button(tr('Chi tiết'),'admin-job',`data-id="${j.id}"`,'small')}</td></tr>`));
  return (items.length?body:empty(tr('Không có kết quả'),tr('Đổi bộ lọc để xem các mục khác.')))+pagination(p,'operations');
}
export function adminOperations(s){
  return head(tr('Vận hành bot.'),tr('Theo dõi tác vụ, lỗi worker và các phiên bản bot đã nộp.'),button(tr('Làm mới'),'refresh'))+
    tabs([['jobs',tr('Tác vụ & worker')],['submissions',tr('Phiên bản bot')]],s.opsTab||'jobs','ops-tab')+
    l10n`<div class="admin-filters"><label class="field"><span>Tìm kiếm</span><input class="input" type="search" name="ops-search" value="${esc(s.opsSearch||'')}" placeholder="Mã tác vụ, phiên bản, tên đội…"></label><label class="field"><span>Đội</span>${select('ops-team',[['',tr('Tất cả đội / giải')],...s.accounts.map(a=>[a.team_id,a.team.name])],s.opsTeam||'',false)}</label>${s.opsTab!=='submissions'?l10n`<label class="field"><span>Trạng thái</span>${select('ops-status',[['',tr('Tất cả')],...['queued','building','validating','benchmarking','playing','completed','failed','aborted'].map(v=>[v,statusLabel(v)])],s.opsStatus||'',false)}</label><label class="field"><span>Loại</span>${select('ops-kind',[['',tr('Tất cả')],['benchmark',tr('Kiểm tra')],['match',tr('Trận đấu')]],s.opsKind||'',false)}</label>`:''}</div>`+
    panel(tr('Bot trùng hash'),l10n`<p>Chỉ là dấu hiệu để BTC rà soát; bot mẫu cũng có thể trùng. Không tự phạt đội.</p>${s.duplicates?.length?table([tr('Hash bot'),tr('Các đội')],s.duplicates.map(d=>`<tr><td class="mono">${esc(d.bot_hash)}</td><td>${d.teams.map(t=>esc(t.name)).join(' · ')}</td></tr>`)):empty(tr('Chưa có bot trùng giữa các đội'))}`)+
    panel(s.opsTab==='submissions'?tr('Source đã nộp'):tr('Danh sách tác vụ'),`<div id="operations-table">${operationsBody(s)}</div>`)+note(tr('Kết quả thi đấu và source đã nộp được giữ nguyên. Trận chính thức lỗi được chạy lại từ trang giải; không tự gán thắng/thua hoặc xóa báo cáo.'));
}
